CREATE TABLE IF NOT EXISTS ai_message_feedback (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,message_id BIGINT NOT NULL REFERENCES ai_messages(id) ON DELETE CASCADE,rating SMALLINT NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,message_id));
CREATE TABLE IF NOT EXISTS workspace_preferences (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,module_slug TEXT NOT NULL,custom_instructions TEXT NOT NULL DEFAULT '',temperature DOUBLE PRECISION NOT NULL DEFAULT 0.7 CHECK(temperature BETWEEN 0.1 AND 1.0),pinned BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(user_id,module_slug));
CREATE TABLE IF NOT EXISTS ai_response_versions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,module_slug TEXT NOT NULL,user_message_id BIGINT NOT NULL REFERENCES ai_messages(id) ON DELETE CASCADE,response_text TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ai_response_versions_user_idx ON ai_response_versions(user_id,module_slug,created_at DESC);
CREATE TABLE IF NOT EXISTS ai_model_events (id BIGSERIAL PRIMARY KEY,event_type TEXT NOT NULL,model TEXT NOT NULL,duration_ms BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ai_model_events_created_idx ON ai_model_events(created_at DESC);
